import { getComponentByName } from '../utils/dataLoader.js';

/**
 * Get installation and setup guide for a component
 */
export async function getInstallGuide(args) {
  const { 
    componentName, 
    projectType = 'vite', 
    techStack = 'js-css' 
  } = args;

  try {
    // Find component
    const component = getComponentByName(componentName);
    if (!component) {
      return {
        content: [
          {
            type: 'text',
            text: `Component "${componentName}" not found. Use search-react-bits-components to find available components.`
          }
        ]
      };
    }

    // Generate installation guide
    const guide = generateInstallationGuide(componentName, component, projectType, techStack);

    return {
      content: [
        {
          type: 'text',
          text: guide
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error generating install guide: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Generate comprehensive installation guide
 */
function generateInstallationGuide(componentName, component, projectType, techStack) {
  let output = `# Installation Guide: ${capitalizeFirst(componentName)}\n\n`;
  
  output += `**Component:** ${componentName}\n`;
  output += `**Category:** ${component.category}\n`;
  output += `**Project Type:** ${projectType}\n`;
  output += `**Tech Stack:** ${techStack}\n\n`;

  // Method 1: JSRepo CLI (Recommended)
  output += `## Method 1: JSRepo CLI (Recommended)\n\n`;
  output += `The easiest way to install React Bits components:\n\n`;
  
  output += `### Step 1: Install JSRepo CLI\n`;
  output += `\`\`\`bash\nnpm install -g jsrepo\n\`\`\`\n\n`;
  
  output += `### Step 2: Add Component\n`;
  output += `\`\`\`bash\n`;
  output += `jsrepo add react-bits/${componentName}\n`;
  output += `\`\`\`\n\n`;

  output += `This will automatically:\n`;
  output += `- Download the component code\n`;
  output += `- Install required dependencies\n`;
  output += `- Set up the correct file structure\n\n`;

  // Method 2: Manual Installation
  output += `## Method 2: Manual Installation\n\n`;
  
  // Dependencies
  const dependencies = getComponentDependencies(componentName, component.category, techStack);
  
  output += `### Step 1: Install Dependencies\n`;
  output += `\`\`\`bash\n`;
  output += `npm install ${dependencies.runtime.join(' ')}\n`;
  if (dependencies.dev.length > 0) {
    output += `npm install -D ${dependencies.dev.join(' ')}\n`;
  }
  output += `\`\`\`\n\n`;

  // Project-specific setup
  output += getProjectSpecificSetup(projectType, techStack);

  // Component integration
  output += `### Step 3: Add Component to Your Project\n\n`;
  output += `1. Get the component code using:\n`;
  output += `   \`get-react-bits-component --componentName ${componentName} --version ${techStack}\`\n\n`;
  output += `2. Create a new file in your components directory:\n`;
  const fileExtension = techStack.includes('ts') ? 'tsx' : 'jsx';
  output += `   \`src/components/${capitalizeFirst(componentName)}.${fileExtension}\`\n\n`;
  output += `3. Copy the component code into the file\n\n`;
  output += `4. Import and use in your application:\n`;
  output += `\`\`\`jsx\n`;
  output += `import ${capitalizeFirst(componentName)} from './components/${capitalizeFirst(componentName)}';\n\n`;
  output += `function App() {\n`;
  output += `  return (\n`;
  output += `    <div>\n`;
  output += `      <${capitalizeFirst(componentName)} />\n`;
  output += `    </div>\n`;
  output += `  );\n`;
  output += `}\n`;
  output += `\`\`\`\n\n`;

  // Troubleshooting
  output += `## Troubleshooting\n\n`;
  output += getTroubleshootingGuide(componentName, component.category, techStack, projectType);

  // Next steps
  output += `## Next Steps\n\n`;
  output += `1. **Customize the component** - Check available props and styling options\n`;
  output += `2. **View demo** - Use \`get-react-bits-demo --componentName ${componentName}\` for examples\n`;
  output += `3. **Explore similar components** - Use \`search-react-bits-components --category ${component.category}\`\n`;
  output += `4. **Check documentation** - Visit [reactbits.dev](https://reactbits.dev) for full docs\n\n`;

  // Additional resources
  output += `## Additional Resources\n\n`;
  output += `- **React Bits Website**: https://reactbits.dev\n`;
  output += `- **GitHub Repository**: https://github.com/davidhdev/react-bits\n`;
  output += `- **JSRepo Documentation**: https://jsrepo.dev\n`;
  
  if (techStack.includes('tailwind')) {
    output += `- **Tailwind CSS**: https://tailwindcss.com\n`;
  }
  
  if (techStack.includes('ts')) {
    output += `- **TypeScript**: https://typescriptlang.org\n`;
  }

  return output;
}

/**
 * Get component dependencies based on category and tech stack
 */
function getComponentDependencies(componentName, category, techStack) {
  const runtime = ['react', 'react-dom'];
  const dev = [];

  // Base dependencies by category
  switch (category) {
    case 'animations':
      runtime.push('framer-motion');
      break;
    case 'components':
      runtime.push('framer-motion');
      if (componentName.includes('3d') || componentName === 'model-viewer') {
        runtime.push('three', '@react-three/fiber', '@react-three/drei');
      }
      break;
    case 'backgrounds':
      runtime.push('framer-motion');
      if (['particles', 'liquid-chrome', 'orb'].includes(componentName)) {
        runtime.push('three', '@react-three/fiber', '@react-three/drei');
      }
      break;
  }

  // Tech stack specific dependencies
  if (techStack.includes('tailwind')) {
    runtime.push('tailwindcss');
    dev.push('@tailwindcss/vite');
  }

  if (techStack.includes('ts')) {
    dev.push('typescript', '@types/react', '@types/react-dom');
  }

  // Component-specific dependencies
  const componentSpecific = {
    'dock': ['react-use-gesture'],
    'infinite-scroll': ['react-intersection-observer'],
    'particles': ['three', '@react-three/fiber'],
    'model-viewer': ['three', '@react-three/fiber', '@react-three/drei'],
    'fluid-glass': ['three', '@react-three/fiber', '@react-three/drei']
  };

  if (componentSpecific[componentName]) {
    runtime.push(...componentSpecific[componentName]);
  }

  return {
    runtime: [...new Set(runtime)],
    dev: [...new Set(dev)]
  };
}

/**
 * Get project-specific setup instructions
 */
function getProjectSpecificSetup(projectType, techStack) {
  let output = `### Step 2: Project Setup\n\n`;

  switch (projectType) {
    case 'vite':
      output += getViteSetup(techStack);
      break;
    case 'nextjs':
      output += getNextJSSetup(techStack);
      break;
    case 'cra':
      output += getCRASetup(techStack);
      break;
    case 'remix':
      output += getRemixSetup(techStack);
      break;
    default:
      output += getGenericSetup(techStack);
  }

  return output;
}

/**
 * Vite setup instructions
 */
function getViteSetup(techStack) {
  let setup = `**Vite Configuration:**\n\n`;
  
  if (techStack.includes('tailwind')) {
    setup += `1. Configure Tailwind CSS in \`vite.config.js\`:\n`;
    setup += `\`\`\`javascript\n`;
    setup += `import { defineConfig } from 'vite'\n`;
    setup += `import react from '@vitejs/plugin-react'\n`;
    setup += `import tailwindcss from '@tailwindcss/vite'\n\n`;
    setup += `export default defineConfig({\n`;
    setup += `  plugins: [react(), tailwindcss()],\n`;
    setup += `})\n`;
    setup += `\`\`\`\n\n`;
  }

  if (techStack.includes('ts')) {
    setup += `2. Ensure TypeScript is configured in \`tsconfig.json\`\n\n`;
  }

  return setup;
}

/**
 * Next.js setup instructions
 */
function getNextJSSetup(techStack) {
  let setup = `**Next.js Configuration:**\n\n`;
  
  if (techStack.includes('tailwind')) {
    setup += `1. Configure Tailwind in \`tailwind.config.js\`:\n`;
    setup += `\`\`\`javascript\n`;
    setup += `module.exports = {\n`;
    setup += `  content: [\n`;
    setup += `    './pages/**/*.{js,ts,jsx,tsx}',\n`;
    setup += `    './components/**/*.{js,ts,jsx,tsx}',\n`;
    setup += `  ],\n`;
    setup += `  theme: {\n`;
    setup += `    extend: {},\n`;
    setup += `  },\n`;
    setup += `  plugins: [],\n`;
    setup += `}\n`;
    setup += `\`\`\`\n\n`;
    
    setup += `2. Import Tailwind in \`styles/globals.css\`:\n`;
    setup += `\`\`\`css\n`;
    setup += `@tailwind base;\n`;
    setup += `@tailwind components;\n`;
    setup += `@tailwind utilities;\n`;
    setup += `\`\`\`\n\n`;
  }

  return setup;
}

/**
 * Create React App setup instructions
 */
function getCRASetup(techStack) {
  let setup = `**Create React App Configuration:**\n\n`;
  
  if (techStack.includes('tailwind')) {
    setup += `1. Install and configure Tailwind CSS:\n`;
    setup += `\`\`\`bash\n`;
    setup += `npx tailwindcss init -p\n`;
    setup += `\`\`\`\n\n`;
    
    setup += `2. Configure \`tailwind.config.js\`:\n`;
    setup += `\`\`\`javascript\n`;
    setup += `module.exports = {\n`;
    setup += `  content: ["./src/**/*.{js,jsx,ts,tsx}"],\n`;
    setup += `  theme: { extend: {} },\n`;
    setup += `  plugins: [],\n`;
    setup += `}\n`;
    setup += `\`\`\`\n\n`;
  }

  return setup;
}

/**
 * Remix setup instructions
 */
function getRemixSetup(techStack) {
  let setup = `**Remix Configuration:**\n\n`;
  
  if (techStack.includes('tailwind')) {
    setup += `1. Configure Tailwind in your Remix app\n`;
    setup += `2. Add Tailwind directives to your CSS file\n\n`;
  }

  return setup;
}

/**
 * Generic setup instructions
 */
function getGenericSetup(techStack) {
  let setup = `**General React Project Setup:**\n\n`;
  
  if (techStack.includes('tailwind')) {
    setup += `1. Configure Tailwind CSS according to your build tool\n`;
    setup += `2. Ensure Tailwind directives are imported in your CSS\n\n`;
  }

  return setup;
}

/**
 * Get troubleshooting guide
 */
function getTroubleshootingGuide(componentName, category, techStack, projectType) {
  let guide = `### Common Issues\n\n`;
  
  guide += `**1. Module not found errors:**\n`;
  guide += `- Ensure all dependencies are installed\n`;
  guide += `- Check import paths are correct\n`;
  guide += `- Restart your development server\n\n`;

  if (techStack.includes('tailwind')) {
    guide += `**2. Tailwind styles not working:**\n`;
    guide += `- Verify Tailwind is properly configured\n`;
    guide += `- Check that your build process includes Tailwind\n`;
    guide += `- Ensure component files are in Tailwind's content paths\n\n`;
  }

  if (category === 'backgrounds' || componentName.includes('3d')) {
    guide += `**3. 3D/WebGL issues:**\n`;
    guide += `- Check browser WebGL support\n`;
    guide += `- Ensure Three.js dependencies are installed\n`;
    guide += `- Test on different devices for performance\n\n`;
  }

  guide += `**4. Animation performance:**\n`;
  guide += `- Use React.memo() for frequently re-rendering components\n`;
  guide += `- Consider reducing animation complexity on mobile\n`;
  guide += `- Test with React DevTools Profiler\n\n`;

  guide += `**5. TypeScript errors:**\n`;
  if (techStack.includes('ts')) {
    guide += `- Ensure @types packages are installed\n`;
    guide += `- Check TypeScript configuration\n`;
    guide += `- Add type declarations if needed\n\n`;
  } else {
    guide += `- Switch to TypeScript version if you need type safety\n\n`;
  }

  return guide;
}

/**
 * Utility function
 */
function capitalizeFirst(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}
